  // ── Helpers ──

  String _statusLabel(String status) {
    switch (status.toUpperCase()) {
      case 'ACCEPTED':
        return 'Dikonfirmasi';
      case 'PENDING':
        return 'Menunggu';
      case 'REJECTED':
        return 'Ditolak';
      default:
        return status;
    }
  }

  Color _urgencyColor(String urgency) {
    final u = urgency.toLowerCase();
    if (u.contains('darurat') || u.contains('kritis')) return Colors.red.shade700;
    if (u.contains('penting')) return Colors.amber.shade700;
    return Colors.blue.shade600;
  }

  List<DashboardCardItem> get _displayCardItems {
    final List<DashboardCardItem> cardList = [];

    for (final order in widget.orders.where((o) => o.isActiveDashboardOrder)) {
      if (order.items.isNotEmpty) {
        for (final item in order.items) {
          String scheduleStr = item.scheduledDate;
          if (item.scheduledTimeStart.isNotEmpty) {
            scheduleStr = '${item.scheduledDate} • ${item.scheduledTimeStart}';
            if (item.scheduledTimeEnd.isNotEmpty) {
              scheduleStr += ' - ${item.scheduledTimeEnd} WIB';
            } else {
              scheduleStr += ' WIB';
            }
          }

          cardList.add(
            DashboardCardItem(
              parentOrder: order,
              title: item.itemName,
              dateSchedule: scheduleStr,
              location: item.locationName.isNotEmpty
                  ? item.locationName
                  : order.displayAddress,
              penerimaName: order.penerimaName,
            ),
          );
        }
      } else {
        cardList.add(
          DashboardCardItem(
            parentOrder: order,
            title: order.categoryName,
            dateSchedule: order.fullScheduleLabel,
            location: order.displayAddress,
            penerimaName: order.penerimaName,
          ),
        );
      }
    }

    return cardList;
  }

