                                  color: Colors.black45,
                                  offset: Offset(0, 1),
                                ),
                              ],
                            ),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),

            // ── Urgency accent strip ──
            Container(height: 3, color: urgencyColor),

            // ── Card body ──
            Padding(
              padding: const EdgeInsets.fromLTRB(12, 10, 12, 12),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  // Category / Item Misa Name badge
                  Container(
                    padding: const EdgeInsets.symmetric(
                        horizontal: 7, vertical: 2.5),
                    decoration: BoxDecoration(
                      color: const Color(0xFF1E5399).withOpacity(0.08),
                      borderRadius: BorderRadius.circular(6),
                    ),
                    child: Text(
                      item.title,
                      style: const TextStyle(
                        fontSize: 9.5,
                        fontWeight: FontWeight.w700,
                        color: Color(0xFF1E5399),
                      ),
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
                  const SizedBox(height: 6),
                  // Nama penerima sakramen — main title
                  Text(
                    item.penerimaName,
                    style: const TextStyle(
                      fontSize: 13.5,
                      fontWeight: FontWeight.bold,
                      color: Color(0xFF0F172A),
                      height: 1.2,
                    ),
                    maxLines: 2,
                    overflow: TextOverflow.ellipsis,
                  ),
                  const SizedBox(height: 5),
                  // Gender + Usia
                  if (order.genderLabel.isNotEmpty || order.usiaLabel.isNotEmpty)
                    Padding(
                      padding: const EdgeInsets.only(bottom: 5),
                      child: Row(
                        children: [
                          if (order.genderLabel.isNotEmpty) ...[
                            const Icon(Icons.person_outline_rounded,
                                size: 12, color: Color(0xFF64748B)),
                            const SizedBox(width: 3),
                            Text(
                              order.genderLabel,
                              style: const TextStyle(
                                  fontSize: 10.5, color: Color(0xFF64748B)),
                            ),
                          ],
                          if (order.genderLabel.isNotEmpty &&
                              order.usiaLabel.isNotEmpty)
                            const SizedBox(width: 8),
                          if (order.usiaLabel.isNotEmpty) ...[
                            const Icon(Icons.cake_outlined,
                                size: 12, color: Color(0xFF64748B)),
                            const SizedBox(width: 3),
                            Text(
                              order.usiaLabel,
                              style: const TextStyle(
                                  fontSize: 10.5, color: Color(0xFF64748B)),
                            ),
                          ],
                        ],
                      ),
                    ),
                  // Date + Start Time + urgency pill
                  Row(
                    children: [
                      const Icon(Icons.calendar_today_outlined,
                          size: 11, color: Color(0xFF94A3B8)),
                      const SizedBox(width: 4),
                      Expanded(
                        child: Text(
                          item.dateSchedule,
                          style: const TextStyle(
                            fontSize: 10,
                            color: Color(0xFF64748B),
                            fontWeight: FontWeight.w600,
                          ),
                          overflow: TextOverflow.ellipsis,
                        ),
                      ),
                      const SizedBox(width: 4),
                      Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 6, vertical: 2),
                        decoration: BoxDecoration(
                          color: urgencyColor.withOpacity(0.12),
                          borderRadius: BorderRadius.circular(5),
                        ),
                        child: Text(
                          order.urgencyName,
                          style: TextStyle(
                            fontSize: 9,
                            fontWeight: FontWeight.w700,
                            color: urgencyColor,
                          ),
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class DashboardCardItem {
  final Order parentOrder;
  final String title;
  final String dateSchedule;
  final String location;
  final String penerimaName;

  DashboardCardItem({
    required this.parentOrder,
    required this.title,
    required this.dateSchedule,
    required this.location,
    required this.penerimaName,
  });
}
